/* door: event */
#define DOOR_CLOSED ((emb_state_t)0u)
#define DOOR_OPEN ((emb_state_t)1u)
#define DOOR_JAMMED ((emb_state_t)2u)
#define DOOR_STATE_COUNT ((emb_state_t)3u)
#define DOOR_EV_OPEN (EMB_EV_USER + 0u)
#define DOOR_EV_CLOSE (EMB_EV_USER + 1u)
#define DOOR_EV_JAM (EMB_EV_USER + 2u)
typedef struct door {
    emb_task_t task; /* first: the runtime's */
    door_data_t data;
} door_t;
extern door_t door;
#define DOOR_TASK (&door.task)
emb_state_t door_on_closed(door_t *self, const emb_task_event_t *ev);
emb_state_t door_on_open(door_t *self, const emb_task_event_t *ev);
emb_state_t door_on_jammed(door_t *self, const emb_task_event_t *ev);
void door_enter_open(door_t *self);
void door_exit_open(door_t *self);

/* blink: periodic, every 500 ms */
#define BLINK_DARK ((emb_state_t)0u)
#define BLINK_LIT ((emb_state_t)1u)
#define BLINK_STATE_COUNT ((emb_state_t)2u)
typedef struct blink {
    emb_task_t task; /* first: the runtime's */
} blink_t;
extern blink_t blink;
#define BLINK_TASK (&blink.task)
emb_state_t blink_on_dark(blink_t *self);
emb_state_t blink_on_lit(blink_t *self);

